// Exam Monitor Page — Real-time proctoring dashboard for staff/admin
import React, { useEffect, useState, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { io } from 'socket.io-client';
import Layout from '../../components/common/Layout';
import { examAPI } from '../../services/api';

const SEVERITY_COLORS = {
  low: 'bg-yellow-50 border-yellow-200 text-yellow-800',
  medium: 'bg-orange-50 border-orange-200 text-orange-800',
  high: 'bg-red-50 border-red-200 text-red-800',
  critical: 'bg-red-100 border-red-400 text-red-900 font-bold',
};

export default function ExamMonitorPage() {
  const { examId } = useParams();
  const [exam, setExam] = useState(null);
  const [results, setResults] = useState([]);
  const [violations, setViolations] = useState([]);
  const [loading, setLoading] = useState(true);
  const socketRef = useRef(null);

  useEffect(() => {
    Promise.all([
      examAPI.getById(examId),
      examAPI.getResults(examId)
    ]).then(([examData, resultData]) => {
      setExam(examData.exam);
      setResults(resultData.results || []);
    }).finally(() => setLoading(false));

    // Connect socket for real-time violations
    const socket = io(process.env.REACT_APP_API_URL?.replace('/api', '') || 'http://localhost:5000');
    socketRef.current = socket;
    socket.emit('join_monitor', examId);
    socket.on('new_violation', (data) => {
      setViolations(prev => [data, ...prev].slice(0, 50)); // keep last 50
    });

    return () => socket.disconnect();
  }, [examId]);

  if (loading) return <Layout title="Exam Monitor"><div className="flex justify-center py-20"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"/></div></Layout>;

  return (
    <Layout title={`Monitor: ${exam?.title || 'Exam'}`}>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Live Violations Feed */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-xl shadow-sm p-4">
            <div className="flex items-center gap-2 mb-4">
              <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse"/>
              <h3 className="font-bold text-gray-800">Live Violation Feed</h3>
            </div>

            {violations.length === 0 ? (
              <p className="text-gray-400 text-sm text-center py-8">No violations yet. Monitoring active...</p>
            ) : (
              <div className="space-y-2 max-h-96 overflow-y-auto">
                {violations.map((v, i) => (
                  <div key={i} className={`border rounded-lg p-3 text-xs ${SEVERITY_COLORS[v.severity] || SEVERITY_COLORS.medium}`}>
                    <div className="flex justify-between items-start mb-1">
                      <span className="font-semibold uppercase">{v.violation_type?.replace(/_/g, ' ')}</span>
                      <span className="opacity-60">{new Date(v.timestamp || Date.now()).toLocaleTimeString()}</span>
                    </div>
                    {v.student_name && <p className="opacity-80">Student: {v.student_name}</p>}
                    {v.description && <p className="opacity-70 mt-0.5">{v.description}</p>}
                    {v.confidence_score && <p className="opacity-60">Confidence: {(v.confidence_score * 100).toFixed(0)}%</p>}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Student Results Table */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-xl shadow-sm p-4">
            <h3 className="font-bold text-gray-800 mb-4">Student Results ({results.length})</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 text-left text-gray-600">
                  <tr>
                    <th className="px-3 py-2">Student</th>
                    <th className="px-3 py-2">Score</th>
                    <th className="px-3 py-2">%</th>
                    <th className="px-3 py-2">Grade</th>
                    <th className="px-3 py-2">Status</th>
                    <th className="px-3 py-2">Violations</th>
                  </tr>
                </thead>
                <tbody>
                  {results.map(r => (
                    <tr key={r.id} className="border-b border-gray-50 hover:bg-gray-50">
                      <td className="px-3 py-2.5">
                        <p className="font-medium">{r.student_name}</p>
                        <p className="text-xs text-gray-400">{r.roll_number}</p>
                      </td>
                      <td className="px-3 py-2.5">{r.marks_obtained}/{r.total_marks}</td>
                      <td className="px-3 py-2.5">{r.percentage?.toFixed(1)}%</td>
                      <td className="px-3 py-2.5 font-bold">{r.grade}</td>
                      <td className="px-3 py-2.5">
                        <span className={`px-2 py-0.5 rounded-full text-xs ${r.is_passed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                          {r.is_passed ? 'Pass' : 'Fail'}
                        </span>
                      </td>
                      <td className="px-3 py-2.5">
                        <span className={`font-medium ${r.violation_count > 5 ? 'text-red-600' : r.violation_count > 0 ? 'text-yellow-600' : 'text-green-600'}`}>
                          {r.violation_count}
                        </span>
                      </td>
                    </tr>
                  ))}
                  {results.length === 0 && (
                    <tr><td colSpan={6} className="text-center text-gray-400 py-10">No submissions yet</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>

          {/* Exam Info */}
          {exam && (
            <div className="bg-white rounded-xl shadow-sm p-4 mt-4 grid grid-cols-3 gap-4 text-sm">
              <div><p className="text-gray-500 text-xs">Duration</p><p className="font-semibold">{exam.duration_minutes} mins</p></div>
              <div><p className="text-gray-500 text-xs">Total Marks</p><p className="font-semibold">{exam.total_marks}</p></div>
              <div><p className="text-gray-500 text-xs">Pass Marks</p><p className="font-semibold">{exam.pass_marks}</p></div>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
}
